from (
  select created_at, mensagem_usuario, mensagem_agente, nome_app
  from public.historico_mensagens
  where telefone = $1
    and nome_app in ('AGRO-IA', 'AGRO-INTERESSES')
  order by created_at desc
  limit 40
) ultimas
order by created_at asc;

