// Fallback: o output parser nao fechou o JSON. Em vez de deixar o cliente
// sem resposta, manda o texto cru do agente como UMA mensagem.
let txt = '';
try { txt = String($('Saida do Agente').first().json.texto || '').trim(); } catch (e) { txt = ''; }
if (!txt) { return []; }   // sem texto, nao inventa nada
return [{ json: { output: { mensagens: [txt] }, veio_do_fallback: true } }];

// Parse do retorno do divisor de mensagens, a prova de falha.
// Ordem: JSON valido -> JSON dentro de cerca ```  -> texto cru do agente.
// NUNCA devolve vazio quando existe texto, para o cliente nunca ficar sem resposta.
let cru = '';
try { cru = String($('Saida do Agente').first().json.texto || '').trim(); } catch (e) { cru = ''; }

const item = $input.first() ? ($input.first().json || {}) : {};
let bruto = item.text;
if (bruto === undefined || bruto === null) bruto = item.output;
if (bruto === undefined || bruto === null) bruto = item.response;

function tiraCerca(s) {
  const m = String(s).match(/```(?:json)?\s*([\s\S]*?)```/i);
  return m ? m[1].trim() : String(s).trim();
}
function extrai(valor) {
  if (valor === undefined || valor === null) return null;
  if (typeof valor === 'object') {
    if (Array.isArray(valor.mensagens)) return valor.mensagens;
    if (valor.output && Array.isArray(valor.output.mensagens)) return valor.output.mensagens;
    return null;
  }
  const txt = tiraCerca(valor);
  try {
    const o = JSON.parse(txt);
    if (Array.isArray(o.mensagens)) return o.mensagens;
    if (o.output && Array.isArray(o.output.mensagens)) return o.output.mensagens;
  } catch (e) { /* segue para o fallback */ }
  return null;
}

let msgs = extrai(bruto);
let origem = 'parse_ok';
if (!msgs || !msgs.length) { msgs = cru ? [cru] : []; origem = cru ? 'fallback_texto_cru' : 'sem_texto'; }
msgs = msgs.map(function (x) { return String(x === null || x === undefined ? '' : x).trim(); }).filter(function (x) { return x.length > 0; });
if (!msgs.length && cru) { msgs = [cru]; origem = 'fallback_texto_cru'; }
if (!msgs.length) { return []; }   // nao existe texto nenhum: nao inventa

return [{ json: { output: { mensagens: msgs }, parse_origem: origem } }];

